// Navitar training — the Stage's Train button rules (Eddie,
// 2026-11-16, locked):
// - Tapping Train starts a training session for THAT navitar.
// - Each navitar can train ONCE per day.
// - At a higher level, a navitar can train TWICE per day.
// - The limit is per-navitar: training Frostbite never touches
//   Emberwing's allowance.
// The level threshold for the second daily session is a balance
// knob, not a law: TWICE_DAILY_LEVEL is the single place to change
// when Eddie sets the real number.
export const TWICE_DAILY_LEVEL = 15;

export const TRAINING_XP = 25;
export const FEED_BOND = 5;
export const TRAIN_BOND = 3;

const TRAINING_KEY = 'glacer-training-v1';
const CARE_KEY = 'glacer-stage-care-v1';

interface TrainingRecord {
  // Local calendar date the sessions belong to (device-local, so
  // "once a day" rolls over at the player's midnight).
  date: string;
  count: number;
}

type TrainingStore = Record<string, TrainingRecord>;

function today(): string {
  const d = new Date();
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${d.getFullYear()}-${mm}-${dd}`;
}

function loadTraining(): TrainingStore {
  try {
    const raw = localStorage.getItem(TRAINING_KEY);
    const parsed = raw ? JSON.parse(raw) : {};
    return parsed && typeof parsed === 'object' ? (parsed as TrainingStore) : {};
  } catch {
    return {};
  }
}

function saveTraining(store: TrainingStore): void {
  try {
    localStorage.setItem(TRAINING_KEY, JSON.stringify(store));
  } catch {
    // Private mode / quota: cooldown still applies for the session
    // via the caller's state; persistence is best-effort.
  }
}

export function dailyTrainingLimit(level: number): number {
  return level >= TWICE_DAILY_LEVEL ? 2 : 1;
}

export function trainingsUsedToday(navitarName: string): number {
  const rec = loadTraining()[navitarName];
  return rec && rec.date === today() ? rec.count : 0;
}

export function trainingsLeftToday(navitarName: string, level: number): number {
  return Math.max(0, dailyTrainingLimit(level) - trainingsUsedToday(navitarName));
}

export function recordTraining(navitarName: string): void {
  const store = loadTraining();
  const rec = store[navitarName];
  store[navitarName] =
    rec && rec.date === today()
      ? { date: rec.date, count: rec.count + 1 }
      : { date: today(), count: 1 };
  saveTraining(store);
}

// ---- Stage care state (bond / XP / look) --------------------------
// The companion layer's memory: how much this navitar has been fed,
// trained and given — plus its stage look (Modify: crystal tint +
// gear). Local-first, per navitar name, exactly like friends and
// presence already persist in this app.
export interface StageCare {
  bond: number;
  xp: number;
  tint: string; // CSS filter applied to the stage model ('none' = true colours)
  gear: string[];
}

const DEFAULT_CARE: StageCare = { bond: 0, xp: 0, tint: 'none', gear: [] };

type CareStore = Record<string, StageCare>;

function loadCare(): CareStore {
  try {
    const raw = localStorage.getItem(CARE_KEY);
    const parsed = raw ? JSON.parse(raw) : {};
    return parsed && typeof parsed === 'object' ? (parsed as CareStore) : {};
  } catch {
    return {};
  }
}

export function getCare(navitarName: string): StageCare {
  return { ...DEFAULT_CARE, ...(loadCare()[navitarName] ?? {}) };
}

export function updateCare(navitarName: string, updates: Partial<StageCare>): StageCare {
  const store = loadCare();
  const next = { ...getCare(navitarName), ...updates };
  store[navitarName] = next;
  try {
    localStorage.setItem(CARE_KEY, JSON.stringify(store));
  } catch {
    // Best-effort persistence (see saveTraining).
  }
  return next;
}
