import React, { useEffect, useRef, useState } from 'react';
import { Box, Button, Container, Paper, Typography } from '@mui/material';
import { Link as RouterLink, useNavigate } from 'react-router-dom';
import { useNavitarFightClub } from '../contexts/NavitarFightClub';
import { useVenue } from '../contexts/VenueContext';
import { NavitarArtImg } from '../components/NavitarArtImg';
import { SwapNavitarButton } from '../components/QuickSwapNavitar';
import { elementEmoji, resolveNavitarArt } from '../utils/navitarArt';
import { resolveShowcaseModel } from '../utils/modelResolution';
import {
  loadChallengeHandoff,
  saveChallengeHandoff,
  type ChallengeHandoff,
} from '../utils/challengeHandoff';

// The challenge screen (Round 10, Eddie 2026-11-17): ONE screen for
// every "battle someone you met" flow — World Map meet card,
// Networking people, Friends rows, Profile friend challenges. The
// pairing is ALREADY MADE here: your active navitar vs their
// fighter, read from the persisted challenge handoff
// (utils/challengeHandoff.ts), so the screen survives reloads and
// the detour that used to lose the pairing (go choose a fighter,
// come back to nothing) cannot happen: with no fighter chosen, the
// swap/choose sheet opens IN PLACE and the pairing stays on screen.
//
// This screen IS the opponent-approval step for meet challenges
// (battle law: nothing auto-starts). Pressing ⚔️ Battle hands the
// Battle page the venue pending-challenge plus the handoff's
// directStart flag, and the duel starts against exactly this
// opponent — no second gate. The solo /battle entry flow (wild
// picker, Steps 1–3) is untouched for its own entry points.
const Challenge: React.FC = () => {
  const navigate = useNavigate();
  const {
    navitars,
    userNavitar,
    businessNavitars,
    addVenueOpponent,
    addWildOpponent,
    addRemoteOpponent,
  } = useNavitarFightClub();
  const { setPendingChallenge } = useVenue();

  // The handoff is read once on mount: it names a moment (who you
  // just met), not a live feed — re-reading it mid-screen could swap
  // the pairing under the player if another tab wrote a new one.
  const [handoff] = useState<ChallengeHandoff | null>(() => loadChallengeHandoff());
  // The opponent record id as resolved in the pool. Normally the
  // handoff's own id; after a post-reload rebuild it is whatever the
  // adder returned (the adders derive stable ids, so they agree —
  // this state just keeps the screen honest if they ever don't).
  const [resolvedId, setResolvedId] = useState<string | null>(handoff?.opponentId ?? null);
  const rebuildAttemptedFor = useRef<string | null>(null);

  // The opponent pool is in-memory only: if a reload (or a fresh
  // tab) dropped the record, rebuild it from the handoff's fighter
  // data. Attempted once per handoff — if the adder refuses (a
  // locked design can never be an opponent), the screen says so
  // instead of spinning forever.
  useEffect(() => {
    if (!handoff || !resolvedId) return;
    if (businessNavitars.some(n => n.id === resolvedId)) return;
    const attemptKey = `${handoff.opponentId}|${handoff.ts}`;
    if (rebuildAttemptedFor.current === attemptKey) return;
    rebuildAttemptedFor.current = attemptKey;
    const input = handoff.opponent;
    const id =
      handoff.kind === 'wild'
        ? addWildOpponent(input)
        : handoff.kind === 'remote'
          ? addRemoteOpponent(input, handoff.opponentId)
          : addVenueOpponent(input);
    if (id) setResolvedId(id);
  }, [handoff, resolvedId, businessNavitars, addVenueOpponent, addWildOpponent, addRemoteOpponent]);

  const opponent = resolvedId ? (businessNavitars.find(n => n.id === resolvedId) ?? null) : null;
  const rebuildRefused = !!handoff && !opponent && rebuildAttemptedFor.current !== null;

  // 3D honesty (Round 8's one test, shared with Battle Step 1/2):
  // a fighter with no model — its own or a showcase twin's — stands
  // in the arena as its portrait. Said here, on the pairing, before
  // anyone presses Battle.
  const opponentHasModel = opponent ? !!resolveShowcaseModel(opponent, businessNavitars) : false;
  const playerHasModel = userNavitar
    ? !!resolveShowcaseModel(userNavitar, businessNavitars)
    : false;
  // Mirror matches read as one fighter fighting itself without the
  // duel convention (NavitarBattle's duelNames): yours is "Your X".
  const playerDisplayName =
    userNavitar && opponent && opponent.name === userNavitar.name
      ? `Your ${userNavitar.name}`
      : (userNavitar?.name ?? null);

  const startBattle = () => {
    if (!handoff || !opponent || !userNavitar) return;
    // The Battle page's existing plumbing (pre-selected opponent +
    // venue bookkeeping), plus the directStart flag that makes this
    // screen the one approval: the duel starts on arrival.
    setPendingChallenge(opponent.id, handoff.venueId);
    saveChallengeHandoff({ ...handoff, opponentId: opponent.id, directStart: true });
    navigate('/battle');
  };

  if (!handoff) {
    return (
      <Container maxWidth="sm" sx={{ py: 4 }} data-testid="challenge-page">
        <Paper sx={{ p: 3, textAlign: 'center' }} data-testid="challenge-empty">
          <Typography variant="h5" gutterBottom>
            ⚔️ No challenge waiting
          </Typography>
          <Typography variant="body1" color="text.secondary" paragraph>
            Challenges start where you meet people — check in on the World Map, open Networking, or
            pick a friend. When you choose to battle someone, their matchup lands here, already
            paired with your fighter.
          </Typography>
          <Box sx={{ display: 'flex', gap: 1, justifyContent: 'center', flexWrap: 'wrap' }}>
            <Button component={RouterLink} to="/map" variant="contained">
              World Map
            </Button>
            <Button component={RouterLink} to="/networking" variant="outlined">
              Networking
            </Button>
            <Button component={RouterLink} to="/friends" variant="outlined">
              Friends
            </Button>
            <Button component={RouterLink} to="/battle" variant="outlined">
              Battle Arena
            </Button>
          </Box>
        </Paper>
      </Container>
    );
  }

  const fighterBox = (
    side: 'you' | 'them',
    name: string | null,
    sub: string,
    art: string | null | undefined,
    element: string
  ) => (
    <Box
      sx={{
        flex: '1 1 130px',
        textAlign: 'center',
        p: 1.5,
        borderRadius: 3,
        bgcolor: 'rgba(255,255,255,0.04)',
        border: '1px solid rgba(120, 200, 225, 0.16)',
      }}
    >
      <Typography variant="caption" color="text.secondary" sx={{ letterSpacing: '0.08em' }}>
        {side === 'you' ? 'YOU' : 'OPPONENT'}
      </Typography>
      <Box sx={{ display: 'flex', justifyContent: 'center', my: 1 }}>
        <NavitarArtImg
          src={art ?? ''}
          alt={`${name ?? 'Fighter'} art`}
          element={element}
          fit="contain"
          style={{ width: 110, height: 110, borderRadius: 16, objectFit: 'contain' }}
        />
      </Box>
      <Typography variant="subtitle1" sx={{ fontWeight: 800, lineHeight: 1.2 }}>
        {elementEmoji(element)} {name ?? '—'}
      </Typography>
      <Typography variant="body2" color="text.secondary">
        {sub}
      </Typography>
    </Box>
  );

  return (
    <Container maxWidth="sm" sx={{ py: 4 }} data-testid="challenge-page">
      <Typography variant="h4" gutterBottom align="center">
        ⚔️ Battle challenge
      </Typography>
      <Typography
        variant="body1"
        color="text.secondary"
        align="center"
        sx={{ mb: 3 }}
        data-testid="challenge-intro"
      >
        {handoff.personName
          ? `You met ${handoff.personName}${handoff.venueName ? ` at ${handoff.venueName}` : ''}. This is the matchup — swap your fighter if you like, then battle.`
          : `A wild ${handoff.opponent.name} blocks your path. This is the matchup — swap your fighter if you like, then battle.`}
      </Typography>

      <Paper sx={{ p: 2.5, mb: 3 }}>
        <Box
          sx={{ display: 'flex', gap: 1.5, alignItems: 'stretch', flexWrap: 'wrap' }}
          data-testid="challenge-pairing"
        >
          {fighterBox(
            'you',
            playerDisplayName,
            userNavitar
              ? `Lv. ${userNavitar.level} · ${userNavitar.element}`
              : 'No fighter chosen yet',
            userNavitar ? resolveNavitarArt(userNavitar.imageUrl, userNavitar.name) : null,
            userNavitar?.element ?? 'ice'
          )}
          <Box
            sx={{
              alignSelf: 'center',
              mx: 'auto',
              width: 44,
              height: 44,
              borderRadius: '50%',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontWeight: 900,
              bgcolor: '#e8912d',
              color: '#081a24',
              flexShrink: 0,
            }}
          >
            VS
          </Box>
          {fighterBox(
            'them',
            opponent?.name ?? handoff.opponent.name,
            opponent
              ? `Lv. ${opponent.level} · ${opponent.element}`
              : `Lv. ${handoff.opponent.level} · ${handoff.opponent.element}`,
            opponent
              ? (opponent.imageUrl ?? resolveNavitarArt(undefined, opponent.name))
              : (handoff.opponent.imageUrl ?? resolveNavitarArt(undefined, handoff.opponent.name)),
            opponent?.element ?? handoff.opponent.element
          )}
        </Box>

        {handoff.personName && (
          <Typography variant="body2" color="text.secondary" align="center" sx={{ mt: 2 }}>
            {handoff.personName} fields {opponent?.name ?? handoff.opponent.name} — you field{' '}
            {playerDisplayName ?? 'your chosen fighter'}.
          </Typography>
        )}
        {opponent && !opponentHasModel && (
          <Typography
            variant="body2"
            color="text.secondary"
            align="center"
            sx={{ mt: 1 }}
            data-testid="challenge-opponent-no-model"
          >
            {opponent.name} has no 3D model yet — it will stand in the arena as its portrait.
          </Typography>
        )}
        {userNavitar && !playerHasModel && (
          <Typography
            variant="body2"
            color="text.secondary"
            align="center"
            sx={{ mt: 1 }}
            data-testid="challenge-player-no-model"
          >
            {userNavitar.name} has no 3D model yet — in the arena it will fight as its portrait.
            Swap to a fighter with a <strong>3D</strong> tag to battle in full 3D.
          </Typography>
        )}
        <Typography variant="body2" color="text.secondary" align="center" sx={{ mt: 1 }}>
          {handoff.demo
            ? 'Demo person — met on this device; the duel plays out here and banks like every duel.'
            : 'Your friend’s navitar, dueled here — points and XP bank on this device, like every duel.'}
        </Typography>
      </Paper>

      {rebuildRefused ? (
        <Paper sx={{ p: 3, mb: 3, textAlign: 'center' }} data-testid="challenge-refused">
          <Typography variant="body1" paragraph>
            {handoff.opponent.name} can’t be fielded as an opponent right now, so this challenge
            can’t go ahead.
          </Typography>
          <Button variant="contained" onClick={() => navigate(handoff.returnTo)}>
            ← Back to {handoff.sourceLabel}
          </Button>
        </Paper>
      ) : !userNavitar ? (
        <Paper
          sx={{ p: 3, mb: 3, textAlign: 'center', border: '1px solid', borderColor: '#e8912d' }}
          data-testid="challenge-no-fighter"
        >
          <Typography variant="h6" gutterBottom>
            Choose your fighter
          </Typography>
          <Typography variant="body1" color="text.secondary" paragraph>
            {navitars.length === 0
              ? 'You have no navitars yet. Adopt or create one in the Navidex — this challenge stays saved here, and the pairing will be waiting when you come back.'
              : 'Pick the navitar that fights for you — right here, no detour. The pairing stays on this screen while you choose.'}
          </Typography>
          <Box data-testid="challenge-choose">
            <SwapNavitarButton label="Choose your fighter" variant="contained" />
          </Box>
        </Paper>
      ) : (
        <Box
          sx={{
            display: 'flex',
            gap: 1.5,
            justifyContent: 'center',
            flexWrap: 'wrap',
            mb: 3,
          }}
        >
          <Button
            variant="contained"
            color="primary"
            size="large"
            disabled={!opponent}
            onClick={startBattle}
            data-testid="challenge-battle"
            sx={{ px: 4, py: 1.5, fontSize: '1.1rem', fontWeight: 'bold' }}
          >
            ⚔️ Battle
          </Button>
          <Box data-testid="challenge-swap">
            <SwapNavitarButton label="🔄 Swap fighter" size="large" variant="outlined" />
          </Box>
        </Box>
      )}

      <Box sx={{ textAlign: 'center' }}>
        <Button onClick={() => navigate(handoff.returnTo)} data-testid="challenge-back">
          ← Back to {handoff.sourceLabel}
        </Button>
      </Box>
    </Container>
  );
};

export default Challenge;
