import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Box, Button, Chip, Container, Paper, TextField, Typography } from '@mui/material';
import { Link as RouterLink, useNavigate } from 'react-router-dom';
import { PersonStatusChip } from '../components/NetworkingStatus';
import { usePresence } from '../contexts/PresenceContext';
import { useVenue } from '../contexts/VenueContext';
import { useNavitarFightClub } from '../contexts/NavitarFightClub';
import { saveChallengeHandoff } from '../utils/challengeHandoff';
import { loadFriends } from '../utils/friends';
import { matchReasonFor, type MatchReason } from '../utils/presence';
import {
  allDemoPeople,
  demoAccepts,
  loadSocial,
  resolveFriendRequest,
  saveSocial,
  type DemoGroup,
  type SocialState,
} from '../utils/social';

// Friends — the demo social layer (Option C preview build, Eddie
// 2026-11-16; spec: social-friends-groups-navitar-suggestions-spec.md).
//
// HONEST FRAMING: everything here is a single-device demo. The
// people are the game's demo personas, their answers are simulated
// on this device, and state persists in localStorage only. Real
// cross-player friends, groups and chats are Phase 2.
//
// The laws, visibly enforced:
// - Friend requests: nobody is added without accepting. An accept
//   lands the person in the real glacer-friends list (Profile +
//   World Map friend pins read it); a decline is polite and final,
//   handled gracefully by the navitar.
// - Groups are player-made and player-run; invites are
//   accept/decline, members only ever see the group if they said yes.
// - Group chats: one per group, plus chat-first threads started
//   straight from a friend selection. Anyone can leave. Navitars
//   wingman only when the player's presence allows (Just here /
//   Invisible = the navitar stays out).
// - Navitar suggestions: the navitar SUGGESTS, naming the reason and
//   the context. The human approves or passes FIRST; only then does
//   the other side get asked (simulated), and only a yes on both
//   sides makes an introduction. Never auto-connect, never a forced
//   chat or battle. Dating suggestions exist only on mutual opt-in
//   (the presence "here for dating" setting, OFF by default) and are
//   never shown to anyone who hasn't opted in.
// - Blocking is total: no requests, suggestions, challenges or chat.
// - Safety without being nosy: flag-and-notify only — "that's not
//   how we operate here" — and no records are kept on people.

const CONTEXT_LABEL: Record<MatchReason['kind'], string> = {
  business: 'Business',
  interest: 'Networking interests',
  dating: 'Dating',
};

const SCRIPTED_REPLIES = [
  'Let’s run it back at the next venue night 👊',
  'My navitar has been talking about that battle all day.',
  'I’m in — name the place and I’ll be there.',
  'Coffee first, then we battle. House rules.',
];

const Friends: React.FC = () => {
  const { networkingStatus, visibility, hereForDating, businessName, businessIndustry, interests } =
    usePresence();
  const { checkedInVenueId } = useVenue();
  const { addVenueOpponent } = useNavitarFightClub();
  const navigate = useNavigate();

  // ⚔️ Battle on a friend (Round 10): direct, like every meet
  // surface — their navitar becomes a challengeable opponent (the
  // shared venue adder, so the record is the same one the map's
  // meet card creates), the handoff carries the pairing + this page
  // as the return surface, and the challenge screen takes it from
  // there. This replaces the old "Challenge from Profile →" link,
  // which sent friend battles to a different system's page.
  const battleFriend = (person: (typeof people)[number]['person']) => {
    const opponentInput = {
      name: person.navitarName,
      element: person.navitarElement,
      level: person.navitarLevel,
      skills: person.navitarSkills,
      imageUrl: person.navitarImage,
      modelUrl: person.navitarModelUrl,
      modelZoom: person.navitarModelZoom,
    };
    const opponentId = addVenueOpponent(opponentInput);
    if (!opponentId) return;
    saveChallengeHandoff({
      opponentId,
      opponent: opponentInput,
      kind: 'venue',
      personName: person.name,
      venueId: '',
      sourceLabel: 'Friends',
      returnTo: '/friends',
      demo: true,
      directStart: false,
      ts: Date.now(),
    });
    navigate('/challenge');
  };

  const [social, setSocial] = useState<SocialState>(() => loadSocial());
  const [friendTick, setFriendTick] = useState(0);
  const timers = useRef<number[]>([]);

  const update = (next: SocialState) => {
    setSocial(next);
    saveSocial(next);
  };

  const later = (fn: () => void, ms: number) => {
    timers.current.push(window.setTimeout(fn, ms));
  };
  useEffect(
    () => () => {
      timers.current.forEach(t => window.clearTimeout(t));
    },
    []
  );

  const people = useMemo(() => allDemoPeople(), []);
  const friendIds = useMemo(() => loadFriends(), [friendTick]); // (friend list reloads when friendTick changes)
  const friendEntries = useMemo(
    () =>
      people.filter(e => friendIds.includes(e.person.id) && !social.blocked.includes(e.person.id)),
    [people, friendIds, social.blocked]
  );

  // Resolve any requests left pending (e.g. the page was closed
  // mid-simulation) shortly after mount.
  useEffect(() => {
    const pending = Object.entries(social.requests).filter(([, s]) => s === 'pending');
    pending.forEach(([personId], i) => {
      later(
        () => {
          setSocial(prev => {
            if (prev.requests[personId] !== 'pending') return prev;
            const { state } = resolveFriendRequest(prev, personId);
            saveSocial(state);
            setFriendTick(t => t + 1);
            return state;
          });
        },
        900 + i * 400
      );
    });
  }, []);

  const suggestionsOff =
    social.suggestionFreq === 'off' || networkingStatus === 'quiet' || visibility === 'invisible';

  const suggestionCandidates = useMemo(() => {
    if (suggestionsOff) return [];
    const settings = {
      networkingStatus,
      visibility,
      hereForBusiness: true,
      hereForNetworking: true,
      hereForDating,
      businessName,
      businessIndustry,
      interests,
    };
    const scored = people
      .filter(
        e =>
          !friendIds.includes(e.person.id) &&
          !social.blocked.includes(e.person.id) &&
          !social.suggestions[e.person.id] &&
          e.person.networkingStatus !== 'quiet'
      )
      .map(e => {
        const real = matchReasonFor(e.person, settings);
        const reason: MatchReason =
          real ??
          ({
            kind: 'interest',
            label: `Same circuit — ${e.venueName}`,
            detail: `You and ${e.person.name} both spend time at ${e.venueName} — same room, same game.`,
          } as MatchReason);
        return { entry: e, reason, tier: real ? 0 : 1 };
      });
    if (social.suggestionFreq === 'venues') {
      if (!checkedInVenueId) return [];
      return scored
        .filter(s => s.entry.venueId === checkedInVenueId)
        .sort((a, b) => a.tier - b.tier)
        .slice(0, 4);
    }
    return scored.sort((a, b) => a.tier - b.tier).slice(0, 4);
  }, [
    people,
    friendIds,
    social.blocked,
    social.suggestions,
    suggestionsOff,
    social.suggestionFreq,
    checkedInVenueId,
    hereForDating,
    businessIndustry,
    interests,
    networkingStatus,
    visibility,
  ]);

  const sendRequest = (personId: string) => {
    update({ ...social, requests: { ...social.requests, [personId]: 'pending' } });
    later(() => {
      setSocial(prev => {
        if (prev.requests[personId] !== 'pending') return prev;
        const { state } = resolveFriendRequest(prev, personId);
        saveSocial(state);
        setFriendTick(t => t + 1);
        return state;
      });
    }, 1400);
  };

  const toggleBlock = (personId: string) => {
    const blocked = social.blocked.includes(personId)
      ? social.blocked.filter(id => id !== personId)
      : [...social.blocked, personId];
    update({ ...social, blocked });
  };

  const approveSuggestion = (personId: string, reasonDetail: string) => {
    update({ ...social, suggestions: { ...social.suggestions, [personId]: 'waiting' } });
    later(() => {
      setSocial(prev => {
        if (prev.suggestions[personId] !== 'waiting') return prev;
        const accepted = demoAccepts(`suggestion:${personId}`);
        const entry = people.find(e => e.person.id === personId);
        const next: SocialState = {
          ...prev,
          suggestions: {
            ...prev.suggestions,
            [personId]: accepted ? 'introduced' : 'declined',
          },
          introductions: accepted
            ? [
                ...prev.introductions,
                {
                  personId,
                  text: `Your navitars did the warm-up, then the wingman intro: “You two should know each other — ${reasonDetail}” Say hi any time from Messages or meet at ${entry?.venueName ?? 'a venue'} — a conversation, never a forced battle.`,
                  ts: Date.now(),
                },
              ]
            : prev.introductions,
        };
        saveSocial(next);
        return next;
      });
    }, 1300);
  };

  const passSuggestion = (personId: string) => {
    update({ ...social, suggestions: { ...social.suggestions, [personId]: 'passed' } });
  };

  // ---- Groups + group chats --------------------------------------
  const [groupName, setGroupName] = useState('');
  const [groupPicks, setGroupPicks] = useState<string[]>([]);
  const [chatPicks, setChatPicks] = useState<string[]>([]);
  const [activeGroupId, setActiveGroupId] = useState<string | null>(null);
  const [draft, setDraft] = useState('');
  const [groupNote, setGroupNote] = useState<string | null>(null);

  const wingmanActive = networkingStatus === 'open' && visibility !== 'invisible';

  const createGroup = (kind: 'group' | 'chat', picks: string[], name: string) => {
    if (picks.length === 0) return;
    const memberIds: string[] = [];
    const declinedIds: string[] = [];
    for (const pid of picks) {
      (demoAccepts(`${kind}:${name}:${pid}`) ? memberIds : declinedIds).push(pid);
    }
    const group: DemoGroup = {
      id: `group-${Date.now()}`,
      name,
      kind,
      memberIds,
      declinedIds,
      left: false,
      messages: wingmanActive
        ? [
            {
              from: 'navitar',
              text:
                kind === 'group'
                  ? 'Your navitar set the room up and introduced everyone who accepted. Wingman mode: on.'
                  : 'Your navitar opened the chat for everyone who accepted. Wingman mode: on.',
              ts: Date.now(),
            },
          ]
        : [],
      createdAt: Date.now(),
    };
    update({ ...social, groups: [group, ...social.groups] });
    setActiveGroupId(group.id);
    setGroupNote(
      memberIds.length > 0
        ? `${memberIds.length} accepted right away${
            declinedIds.length
              ? ` · ${declinedIds.length} passed this time (no hard feelings — invites are always a choice)`
              : ''
          }.`
        : 'Everyone passed this time — nobody is added without a yes, so the room stays empty until someone accepts.'
    );
  };

  const activeGroup = social.groups.find(g => g.id === activeGroupId) ?? null;

  const sendGroupMessage = () => {
    if (!activeGroup || !draft.trim() || activeGroup.left) return;
    const groupId = activeGroup.id;
    const withMine: DemoGroup = {
      ...activeGroup,
      messages: [...activeGroup.messages, { from: 'you', text: draft.trim(), ts: Date.now() }],
    };
    update({ ...social, groups: social.groups.map(g => (g.id === groupId ? withMine : g)) });
    setDraft('');
    const responder = activeGroup.memberIds
      .map(id => people.find(e => e.person.id === id)?.person)
      .find(Boolean);
    if (responder) {
      later(() => {
        setSocial(prev => {
          const g = prev.groups.find(x => x.id === groupId);
          if (!g || g.left) return prev;
          const reply = SCRIPTED_REPLIES[Math.floor(Math.random() * SCRIPTED_REPLIES.length)];
          const next: SocialState = {
            ...prev,
            groups: prev.groups.map(x =>
              x.id === groupId
                ? {
                    ...x,
                    messages: [
                      ...x.messages,
                      { from: 'them', author: responder.name, text: reply, ts: Date.now() },
                    ],
                  }
                : x
            ),
          };
          saveSocial(next);
          return next;
        });
      }, 1000);
    }
  };

  const leaveGroup = (groupId: string) => {
    update({
      ...social,
      groups: social.groups.map(g => (g.id === groupId ? { ...g, left: true } : g)),
    });
  };

  const pickChips = (picks: string[], setPicks: (next: string[]) => void, testPrefix: string) => (
    <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mb: 2 }}>
      {friendEntries.length === 0 && (
        <Typography variant="body2" color="text.secondary">
          No friends yet — accept a friend request below first, then they show up here.
        </Typography>
      )}
      {friendEntries.map(({ person }) => (
        <Chip
          key={person.id}
          label={person.name}
          clickable
          color={picks.includes(person.id) ? 'primary' : 'default'}
          data-testid={`${testPrefix}-${person.id}`}
          onClick={() =>
            setPicks(
              picks.includes(person.id)
                ? picks.filter(id => id !== person.id)
                : [...picks, person.id]
            )
          }
        />
      ))}
    </Box>
  );

  return (
    <Container maxWidth="md" sx={{ py: 4 }} data-testid="friends-page">
      <Typography variant="h4" gutterBottom align="center">
        Friends &amp; Groups
      </Typography>
      <Paper sx={{ p: 2, mb: 3, bgcolor: 'rgba(232,145,45,0.12)' }}>
        <Typography variant="body2">
          🧪 <strong>Demo — on this device only.</strong> These are GLACER’s demo people; their
          answers are simulated here, and everything is saved in this browser. Real cross-player
          friends, groups and chats arrive in Phase 2. Conduct, everywhere on GLACER: safety without
          being nosy — if something looks off it gets flagged with a simple “that’s not how we
          operate here,” and no record is kept on anyone.
        </Typography>
      </Paper>

      {/* ---- Navitar suggestions ---------------------------------- */}
      <Paper sx={{ p: 3, mb: 3 }} data-testid="suggestions-panel">
        <Typography variant="h5" gutterBottom>
          ✨ Your navitar suggests
        </Typography>
        <Typography variant="body2" color="text.secondary" paragraph>
          Your navitar works the room and brings you people worth meeting — always with the reason
          named. Nothing happens without your approval first, and the other side has to say yes too.
          Never auto-connect, never a forced chat or battle.
        </Typography>
        <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mb: 2, alignItems: 'center' }}>
          <Typography variant="body2">Suggestions:</Typography>
          {(['on', 'venues', 'off'] as const).map(freq => (
            <Chip
              key={freq}
              label={freq === 'on' ? 'On' : freq === 'venues' ? 'Only in venues' : 'Off'}
              clickable
              color={social.suggestionFreq === freq ? 'primary' : 'default'}
              onClick={() => update({ ...social, suggestionFreq: freq })}
            />
          ))}
          <Chip
            label={
              networkingStatus === 'quiet'
                ? 'Paused — you’re Just here'
                : visibility === 'invisible'
                  ? 'Paused — you’re Invisible'
                  : 'Presence: suggestions allowed'
            }
            size="small"
            variant="outlined"
          />
        </Box>
        {suggestionsOff ? (
          <Typography variant="body2" color="text.secondary">
            Suggestions are off
            {social.suggestionFreq !== 'off'
              ? ' while your presence is Just here or Invisible — your navitar stays out, by design'
              : ''}
            .
          </Typography>
        ) : social.suggestionFreq === 'venues' && !checkedInVenueId ? (
          <Typography variant="body2" color="text.secondary">
            “Only in venues” is on and you’re not checked in anywhere — check in on the World Map
            and your navitar will work that room.
          </Typography>
        ) : suggestionCandidates.length === 0 ? (
          <Typography variant="body2" color="text.secondary">
            No new suggestions right now — everyone nearby is already a friend, passed, or not open
            to meeting.
          </Typography>
        ) : (
          suggestionCandidates.map(({ entry, reason }) => (
            <Box
              key={entry.person.id}
              sx={{ p: 2, mb: 1.5, borderRadius: 3, bgcolor: 'rgba(255,255,255,0.04)' }}
              data-testid={`suggestion-${entry.person.id}`}
            >
              <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'center' }}>
                <Typography variant="subtitle2">{entry.person.name}</Typography>
                <Chip size="small" color="secondary" label={CONTEXT_LABEL[reason.kind]} />
                <Chip size="small" variant="outlined" label={reason.label} />
              </Box>
              <Typography variant="body2" sx={{ mt: 0.5 }}>
                “{reason.detail} Want me to introduce you?”
              </Typography>
              {social.suggestions[entry.person.id] === 'waiting' ? (
                <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                  Your navitar is doing the warm-up with theirs… waiting on their human’s yes.
                </Typography>
              ) : (
                <Box sx={{ display: 'flex', gap: 1, mt: 1 }}>
                  <Button
                    size="small"
                    variant="contained"
                    onClick={() => approveSuggestion(entry.person.id, reason.detail)}
                  >
                    Approve — introduce us
                  </Button>
                  <Button size="small" onClick={() => passSuggestion(entry.person.id)}>
                    Pass
                  </Button>
                </Box>
              )}
            </Box>
          ))
        )}
        {social.introductions.length > 0 && (
          <Box sx={{ mt: 2 }}>
            <Typography variant="subtitle1" gutterBottom>
              Introductions made
            </Typography>
            {social.introductions.map((intro, i) => {
              const entry = people.find(e => e.person.id === intro.personId);
              return (
                <Typography key={i} variant="body2" sx={{ mb: 1 }}>
                  🤝 <strong>{entry?.person.name ?? 'Someone'}</strong> — {intro.text}
                </Typography>
              );
            })}
          </Box>
        )}
        {Object.entries(social.suggestions)
          .filter(([, s]) => s === 'declined')
          .map(([personId]) => {
            const entry = people.find(e => e.person.id === personId);
            return (
              <Typography key={personId} variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                {entry?.person.name ?? 'They'} passed this time — your navitar handled it
                gracefully. No hard feelings, and it won’t be pushed again.
              </Typography>
            );
          })}
      </Paper>

      {/* ---- People & friend requests ------------------------------ */}
      <Paper sx={{ p: 3, mb: 3 }}>
        <Typography variant="h5" gutterBottom>
          People you’ve met &amp; could meet
        </Typography>
        <Typography variant="body2" color="text.secondary" paragraph>
          Send a friend request — they accept or decline, and nobody is added without a yes. Friends
          can be battled right from here (⚔️ Battle — you’ll see the matchup first), can be invited
          to groups, and can see your home kickback if you choose them.
        </Typography>
        {people.map(({ person, venueName }) => {
          const isFriendNow = friendIds.includes(person.id);
          const req = social.requests[person.id];
          const blocked = social.blocked.includes(person.id);
          return (
            <Box
              key={person.id}
              sx={{
                p: 2,
                mb: 1.5,
                borderRadius: 3,
                bgcolor: 'rgba(255,255,255,0.04)',
                opacity: blocked ? 0.55 : 1,
              }}
              data-testid={`person-${person.id}`}
            >
              <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'center' }}>
                <Typography variant="subtitle2">{person.name}</Typography>
                <PersonStatusChip status={person.networkingStatus} />
                <Chip size="small" variant="outlined" label={venueName} />
                {isFriendNow && <Chip size="small" color="success" label="Friend" />}
                {blocked && <Chip size="small" color="error" label="Blocked" />}
              </Box>
              <Typography variant="body2" color="text.secondary">
                {person.vibe} · with {person.navitarName} (Lv {person.navitarLevel})
              </Typography>
              {blocked ? (
                <Button size="small" sx={{ mt: 0.5 }} onClick={() => toggleBlock(person.id)}>
                  Unblock
                </Button>
              ) : isFriendNow ? (
                <Box sx={{ display: 'flex', gap: 1, mt: 0.5 }}>
                  <Button
                    size="small"
                    variant="contained"
                    data-testid={`battle-${person.id}`}
                    onClick={() => battleFriend(person)}
                  >
                    ⚔️ Battle
                  </Button>
                  <Button size="small" color="error" onClick={() => toggleBlock(person.id)}>
                    Block
                  </Button>
                </Box>
              ) : req === 'pending' ? (
                <Typography variant="body2" sx={{ mt: 0.5 }}>
                  Request sent — waiting on {person.name}…
                </Typography>
              ) : req === 'declined' ? (
                <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>
                  {person.name} passed — your navitar kept it graceful. The door stays closed,
                  politely.
                </Typography>
              ) : (
                <Box sx={{ display: 'flex', gap: 1, mt: 0.5 }}>
                  <Button
                    size="small"
                    variant="outlined"
                    onClick={() => sendRequest(person.id)}
                    data-testid={`request-${person.id}`}
                  >
                    Send friend request
                  </Button>
                  <Button size="small" color="error" onClick={() => toggleBlock(person.id)}>
                    Block
                  </Button>
                </Box>
              )}
            </Box>
          );
        })}
      </Paper>

      {/* ---- Groups ------------------------------------------------- */}
      <Paper sx={{ p: 3, mb: 3 }} data-testid="groups-panel">
        <Typography variant="h5" gutterBottom>
          Your groups
        </Typography>
        <Typography variant="body2" color="text.secondary" paragraph>
          Groups are yours to make and run — GLACER never creates one for you or adds anyone without
          their yes.
        </Typography>
        <TextField
          label="Group name — e.g. Valley battle crew"
          value={groupName}
          onChange={e => setGroupName(e.target.value)}
          fullWidth
          size="small"
          sx={{ mb: 2 }}
        />
        {pickChips(groupPicks, setGroupPicks, 'group-pick')}
        <Button
          variant="contained"
          disabled={!groupName.trim() || groupPicks.length === 0}
          onClick={() => {
            createGroup('group', groupPicks, groupName.trim());
            setGroupName('');
            setGroupPicks([]);
          }}
        >
          Create group &amp; invite
        </Button>

        <Typography variant="subtitle1" sx={{ mt: 3 }} gutterBottom>
          …or start a group chat directly
        </Typography>
        {pickChips(chatPicks, setChatPicks, 'chat-pick')}
        <Button
          variant="outlined"
          disabled={chatPicks.length === 0}
          onClick={() => {
            const names = chatPicks
              .map(id => people.find(e => e.person.id === id)?.person.name ?? '')
              .filter(Boolean)
              .join(', ');
            createGroup('chat', chatPicks, `Chat — ${names}`);
            setChatPicks([]);
          }}
        >
          Start group chat
        </Button>
        {groupNote && (
          <Typography variant="body2" sx={{ mt: 2 }}>
            {groupNote}
          </Typography>
        )}
        {!wingmanActive && (
          <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
            Your presence is Just here / Invisible, so your navitar stays out of group chats — the
            humans can still talk.
          </Typography>
        )}

        {social.groups.length > 0 && (
          <Box sx={{ mt: 3, display: 'flex', flexDirection: 'column', gap: 1.5 }}>
            {social.groups.map(g => (
              <Box
                key={g.id}
                sx={{ p: 2, borderRadius: 3, bgcolor: 'rgba(255,255,255,0.04)' }}
                data-testid={`group-${g.id}`}
              >
                <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'center' }}>
                  <Typography variant="subtitle2">{g.name}</Typography>
                  <Chip
                    size="small"
                    label={g.kind === 'group' ? 'Group' : 'Group chat'}
                    variant="outlined"
                  />
                  <Chip
                    size="small"
                    label={`${g.memberIds.length} member${g.memberIds.length === 1 ? '' : 's'} accepted`}
                  />
                  {g.left && <Chip size="small" color="warning" label="You left" />}
                </Box>
                <Typography variant="body2" color="text.secondary">
                  Members:{' '}
                  {g.memberIds
                    .map(id => people.find(e => e.person.id === id)?.person.name ?? id)
                    .join(', ') || 'none yet'}
                  {g.declinedIds.length > 0 &&
                    ` · Passed: ${g.declinedIds
                      .map(id => people.find(e => e.person.id === id)?.person.name ?? id)
                      .join(', ')}`}
                </Typography>
                <Box sx={{ display: 'flex', gap: 1, mt: 1 }}>
                  <Button
                    size="small"
                    variant={activeGroupId === g.id ? 'contained' : 'outlined'}
                    onClick={() => setActiveGroupId(activeGroupId === g.id ? null : g.id)}
                  >
                    {activeGroupId === g.id ? 'Close chat' : 'Open chat'}
                  </Button>
                  {!g.left && (
                    <Button size="small" color="warning" onClick={() => leaveGroup(g.id)}>
                      Leave
                    </Button>
                  )}
                </Box>
                {activeGroupId === g.id && (
                  <Box sx={{ mt: 2 }}>
                    {g.left ? (
                      <Typography variant="body2" color="text.secondary">
                        You left this {g.kind} — the chat is closed to you. The others carry on
                        without you; leaving is always allowed, no questions.
                      </Typography>
                    ) : (
                      <>
                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1, mb: 2 }}>
                          {g.messages.length === 0 && (
                            <Typography variant="body2" color="text.secondary">
                              No messages yet — say the first word.
                            </Typography>
                          )}
                          {g.messages.map((m, i) => (
                            <Box
                              key={i}
                              sx={{
                                alignSelf: m.from === 'you' ? 'flex-end' : 'flex-start',
                                maxWidth: '85%',
                                p: 1.25,
                                borderRadius: 3,
                                bgcolor:
                                  m.from === 'you'
                                    ? 'rgba(18,165,199,0.25)'
                                    : m.from === 'navitar'
                                      ? 'rgba(232,145,45,0.18)'
                                      : 'rgba(255,255,255,0.07)',
                              }}
                            >
                              <Typography variant="caption" color="text.secondary">
                                {m.from === 'you'
                                  ? 'You'
                                  : m.from === 'navitar'
                                    ? 'Your navitar (wingman)'
                                    : (m.author ?? 'Member')}
                              </Typography>
                              <Typography variant="body2">{m.text}</Typography>
                            </Box>
                          ))}
                        </Box>
                        <Box sx={{ display: 'flex', gap: 1 }}>
                          <TextField
                            value={draft}
                            onChange={e => setDraft(e.target.value)}
                            placeholder="Message the group…"
                            size="small"
                            fullWidth
                            onKeyDown={e => {
                              if (e.key === 'Enter') sendGroupMessage();
                            }}
                          />
                          <Button
                            variant="contained"
                            onClick={sendGroupMessage}
                            disabled={!draft.trim()}
                          >
                            Send
                          </Button>
                        </Box>
                      </>
                    )}
                  </Box>
                )}
              </Box>
            ))}
          </Box>
        )}
      </Paper>

      <Paper sx={{ p: 3, textAlign: 'center', bgcolor: 'rgba(33,150,243,0.08)' }}>
        <Typography variant="h6" gutterBottom>
          Got friends in the house? Run a kickback.
        </Typography>
        <Typography variant="body2" color="text.secondary" paragraph>
          Name your home (a name only — never an address), choose which friends can see it, and host
          a mini venue session at yours.
        </Typography>
        <Button component={RouterLink} to="/kickback" variant="contained" size="large">
          Home Kickbacks →
        </Button>
      </Paper>
    </Container>
  );
};

export default Friends;
