import React, { useMemo, useState } from 'react';
import { Box, Button, Container, Paper, TextField, Typography } from '@mui/material';
import { Link as RouterLink, useSearchParams } from 'react-router-dom';
import {
  FORUM_BOARDS,
  boardName,
  isForumBoardId,
  loadForums,
  newForumId,
  saveForums,
  type ForumBoardId,
  type ForumThread,
} from '../utils/forums';

// Forums — chat boards for meetups and events (Eddie, 2026-11-14).
// One page, three views selected by search params:
//   /forums                          → the two boards + the demo note
//   /forums?board=meetups            → thread list + start-a-thread form
//   /forums?board=meetups&thread=<id> → the thread, replies, reply form
//
// Why search params and not /forums/:board paths: the app is built
// with relative asset paths (package.json homepage "."), so every
// route in GLACER lives exactly one level below /GLACER/ — a nested
// path would resolve the JS bundle relative to /forums/<board>/ and
// the app would not boot there at all (verified in the audit
// harness: SyntaxError from the HTML fallback served as JS). The
// boards keep clean shareable URLs without breaking that contract.
//
// Authorship: you post as your profile display name (the name from
// the Home step / `glacer-display-name`), never anonymously by
// accident — if no name is set yet, posts are signed "You" and the
// form says so. Demo personas seed the boards (utils/forums.ts);
// everything persists to `glacer-forums`.
//
// Honest demo framing (a small note on the Forums home): this is a
// demo community that lives on this device. Real cross-device
// forums arrive with Phase 2 accounts. No fake "live" claims.

const DISPLAY_NAME_KEY = 'glacer-display-name';

function myDisplayName(): string {
  try {
    const name = localStorage.getItem(DISPLAY_NAME_KEY);
    return name && name.trim() ? name.trim() : 'You';
  } catch {
    return 'You';
  }
}

function formatWhen(ts: number): string {
  return new Date(ts).toLocaleDateString(undefined, {
    month: 'short',
    day: 'numeric',
  });
}

const WhenWhereHeader: React.FC<{ thread: ForumThread }> = ({ thread }) => {
  if (!thread.when && !thread.where) return null;
  return (
    <Box
      data-testid="meetup-header"
      sx={{
        display: 'flex',
        gap: 2,
        flexWrap: 'wrap',
        p: 1.5,
        mb: 2,
        borderRadius: 3,
        bgcolor: 'rgba(33,150,243,0.10)',
      }}
    >
      {thread.when && (
        <Typography variant="body2">
          🗓️ <strong>When:</strong> {thread.when}
        </Typography>
      )}
      {thread.where && (
        <Typography variant="body2">
          📍 <strong>Where:</strong> {thread.where}
        </Typography>
      )}
    </Box>
  );
};

const ThreadRow: React.FC<{ thread: ForumThread }> = ({ thread }) => (
  <Paper
    component={RouterLink}
    to={`/forums?board=${thread.board}&thread=${thread.id}`}
    data-testid="forum-thread-row"
    sx={{
      display: 'block',
      p: 2,
      mb: 1.5,
      textDecoration: 'none',
      color: 'inherit',
      borderRadius: 3,
    }}
  >
    <Typography variant="subtitle1">{thread.title}</Typography>
    {(thread.when || thread.where) && (
      <Typography variant="body2" color="text.secondary">
        {[thread.when && `🗓️ ${thread.when}`, thread.where && `📍 ${thread.where}`]
          .filter(Boolean)
          .join('  ·  ')}
      </Typography>
    )}
    <Typography variant="body2" color="text.secondary">
      {thread.author} · {formatWhen(thread.createdAt)} · {thread.replies.length}{' '}
      {thread.replies.length === 1 ? 'reply' : 'replies'}
    </Typography>
  </Paper>
);

const ForumsHome: React.FC<{ threads: ForumThread[] }> = ({ threads }) => (
  <Container maxWidth="md" sx={{ py: 4 }} data-testid="forums-page">
    <Typography variant="h4" gutterBottom align="center">
      Forums
    </Typography>
    <Typography variant="body1" color="text.secondary" align="center" sx={{ mb: 3 }}>
      Where the realm plans its real life — meetups to show up to, events to circle on the calendar.
    </Typography>
    <Paper sx={{ p: 2, mb: 3, bgcolor: 'rgba(255,179,0,0.08)' }} data-testid="forums-demo-note">
      <Typography variant="body2" align="center">
        Demo community — these boards live on this device, seeded with the realm’s demo hosts. Real
        forums, shared by every player, arrive with Phase 2 accounts.
      </Typography>
    </Paper>
    {FORUM_BOARDS.map(board => {
      const boardThreads = threads.filter(t => t.board === board.id);
      const latest = boardThreads[boardThreads.length - 1];
      return (
        <Paper
          key={board.id}
          component={RouterLink}
          to={`/forums?board=${board.id}`}
          data-testid={`board-card-${board.id}`}
          sx={{
            display: 'block',
            p: 3,
            mb: 2,
            textDecoration: 'none',
            color: 'inherit',
            borderRadius: 3,
          }}
        >
          <Typography variant="h5" gutterBottom>
            {board.name}
          </Typography>
          <Typography variant="body2" color="text.secondary" paragraph>
            {board.blurb}
          </Typography>
          <Typography variant="body2">
            {boardThreads.length} {boardThreads.length === 1 ? 'thread' : 'threads'}
            {latest && (
              <>
                {' '}
                · latest: <strong>{latest.title}</strong>
              </>
            )}
          </Typography>
        </Paper>
      );
    })}
  </Container>
);

const BoardView: React.FC<{
  board: ForumBoardId;
  threads: ForumThread[];
  onCreate: (thread: ForumThread) => void;
}> = ({ board, threads, onCreate }) => {
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [when, setWhen] = useState('');
  const [where, setWhere] = useState('');
  const author = myDisplayName();
  const canPost = title.trim() !== '' && body.trim() !== '';

  const submit = () => {
    if (!canPost) return;
    onCreate({
      id: newForumId('thread'),
      board,
      title: title.trim(),
      body: body.trim(),
      author,
      createdAt: Date.now(),
      when: when.trim() || undefined,
      where: where.trim() || undefined,
      replies: [],
    });
    setTitle('');
    setBody('');
    setWhen('');
    setWhere('');
  };

  return (
    <Container maxWidth="md" sx={{ py: 4 }} data-testid="forums-page">
      <Button component={RouterLink} to="/forums" sx={{ mb: 2 }}>
        ← All boards
      </Button>
      <Typography variant="h4" gutterBottom>
        {boardName(board)}
      </Typography>
      <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
        {FORUM_BOARDS.find(b => b.id === board)?.blurb}
      </Typography>

      {threads.map(thread => (
        <ThreadRow key={thread.id} thread={thread} />
      ))}
      {threads.length === 0 && (
        <Typography color="text.secondary" sx={{ mb: 3 }}>
          No threads yet — start the first one below.
        </Typography>
      )}

      <Paper sx={{ p: 3, mt: 3 }}>
        <Typography variant="h6" gutterBottom>
          Start a thread
        </Typography>
        <TextField
          data-testid="thread-create-title"
          label="Title"
          value={title}
          onChange={e => setTitle(e.target.value)}
          fullWidth
          size="small"
          sx={{ mb: 2 }}
        />
        <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap', mb: 2 }}>
          <TextField
            data-testid="thread-create-when"
            label="When"
            placeholder={
              board === 'meetups' ? 'e.g. Saturday, Nov 21 · 5:30 PM' : 'e.g. Friday · 8:00 PM'
            }
            value={when}
            onChange={e => setWhen(e.target.value)}
            size="small"
            sx={{ flex: '1 1 220px' }}
          />
          <TextField
            data-testid="thread-create-where"
            label="Where"
            placeholder="e.g. The Neon Marquee · Hollywood"
            value={where}
            onChange={e => setWhere(e.target.value)}
            size="small"
            sx={{ flex: '1 1 220px' }}
          />
        </Box>
        <TextField
          data-testid="thread-create-body"
          label="Details"
          value={body}
          onChange={e => setBody(e.target.value)}
          fullWidth
          multiline
          minRows={3}
          sx={{ mb: 2 }}
        />
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, flexWrap: 'wrap' }}>
          <Button
            data-testid="thread-create-submit"
            variant="contained"
            disabled={!canPost}
            onClick={submit}
          >
            Post thread
          </Button>
          <Typography variant="body2" color="text.secondary">
            Posting as <strong>{author}</strong>
            {author === 'You' && ' — set your name on the Home page to sign your posts'}
          </Typography>
        </Box>
      </Paper>
    </Container>
  );
};

const ThreadView: React.FC<{
  thread: ForumThread;
  onReply: (threadId: string, body: string) => void;
}> = ({ thread, onReply }) => {
  const [reply, setReply] = useState('');
  const author = myDisplayName();
  const canReply = reply.trim() !== '';

  const submit = () => {
    if (!canReply) return;
    onReply(thread.id, reply.trim());
    setReply('');
  };

  return (
    <Container maxWidth="md" sx={{ py: 4 }} data-testid="forums-page">
      <Button component={RouterLink} to={`/forums?board=${thread.board}`} sx={{ mb: 2 }}>
        ← {boardName(thread.board)}
      </Button>
      <Typography variant="h4" gutterBottom>
        {thread.title}
      </Typography>
      <WhenWhereHeader thread={thread} />
      <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
        {thread.author} · {formatWhen(thread.createdAt)}
      </Typography>
      <Typography variant="body1" sx={{ mb: 4, whiteSpace: 'pre-wrap' }}>
        {thread.body}
      </Typography>

      <Typography variant="h6" gutterBottom>
        {thread.replies.length} {thread.replies.length === 1 ? 'reply' : 'replies'}
      </Typography>
      {thread.replies.map(r => (
        <Paper key={r.id} sx={{ p: 2, mb: 1.5, borderRadius: 3 }} data-testid="forum-reply">
          <Typography variant="body2" color="text.secondary" gutterBottom>
            {r.author} · {formatWhen(r.createdAt)}
          </Typography>
          <Typography variant="body1" sx={{ whiteSpace: 'pre-wrap' }}>
            {r.body}
          </Typography>
        </Paper>
      ))}

      <Paper sx={{ p: 3, mt: 3 }}>
        <Typography variant="h6" gutterBottom>
          Join the conversation
        </Typography>
        <TextField
          data-testid="reply-input"
          label="Your reply"
          value={reply}
          onChange={e => setReply(e.target.value)}
          fullWidth
          multiline
          minRows={2}
          sx={{ mb: 2 }}
        />
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, flexWrap: 'wrap' }}>
          <Button
            data-testid="reply-submit"
            variant="contained"
            disabled={!canReply}
            onClick={submit}
          >
            Post reply
          </Button>
          <Typography variant="body2" color="text.secondary">
            Posting as <strong>{author}</strong>
          </Typography>
        </Box>
      </Paper>
    </Container>
  );
};

const Forums: React.FC = () => {
  const [searchParams] = useSearchParams();
  const [threads, setThreads] = useState<ForumThread[]>(() => loadForums());

  const boardParam = searchParams.get('board') ?? undefined;
  const threadId = searchParams.get('thread');
  const board: ForumBoardId | null = isForumBoardId(boardParam) ? boardParam : null;
  const thread = useMemo(
    () => (threadId ? (threads.find(t => t.id === threadId) ?? null) : null),
    [threads, threadId]
  );

  const createThread = (thread: ForumThread) => {
    setThreads(prev => {
      const next = [...prev, thread];
      saveForums(next);
      return next;
    });
  };

  const addReply = (threadId: string, body: string) => {
    setThreads(prev => {
      const next = prev.map(t =>
        t.id === threadId
          ? {
              ...t,
              replies: [
                ...t.replies,
                { id: newForumId('reply'), author: myDisplayName(), body, createdAt: Date.now() },
              ],
            }
          : t
      );
      saveForums(next);
      return next;
    });
  };

  if (threadId) {
    if (!thread) {
      return (
        <Container maxWidth="md" sx={{ py: 4 }} data-testid="forums-page">
          <Typography variant="h4" gutterBottom>
            Thread not found
          </Typography>
          <Typography color="text.secondary" paragraph>
            That conversation is not on this device’s boards.
          </Typography>
          <Button component={RouterLink} to="/forums" variant="contained">
            Back to the Forums
          </Button>
        </Container>
      );
    }
    return <ThreadView thread={thread} onReply={addReply} />;
  }
  if (board) {
    return (
      <BoardView
        board={board}
        threads={threads.filter(t => t.board === board)}
        onCreate={createThread}
      />
    );
  }
  return <ForumsHome threads={threads} />;
};

export default Forums;
