// Shell error boundary (2026-11-16 hardening): wraps the WHOLE app
// in index.tsx — providers, Navbar, notifications and routes alike.
// The route-level ErrorBoundary only covers page content; a throw in
// a context provider or the app shell used to unmount everything and
// leave a completely blank page with no way back. This boundary is
// deliberately dependency-free (no MUI — the theme provider lives
// inside the tree it protects) and offers the one recovery that
// always works: reload.
import React from 'react';

interface ShellErrorBoundaryState {
  error: Error | null;
}

class ShellErrorBoundary extends React.Component<
  { children: React.ReactNode },
  ShellErrorBoundaryState
> {
  constructor(props: { children: React.ReactNode }) {
    super(props);
    this.state = { error: null };
  }

  static getDerivedStateFromError(error: Error): ShellErrorBoundaryState {
    return { error };
  }

  componentDidCatch(error: Error, info: React.ErrorInfo) {
    console.error('ShellErrorBoundary caught:', error, info.componentStack);
  }

  render() {
    if (this.state.error) {
      return (
        <div
          style={{
            minHeight: '100vh',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            gap: 16,
            padding: 24,
            textAlign: 'center',
            background: '#050f16',
            color: '#eaf6fa',
            fontFamily: '"Roboto", "Helvetica", "Arial", sans-serif',
          }}
        >
          <div style={{ fontSize: 40 }}>🧊</div>
          <div style={{ fontSize: 22, fontWeight: 700 }}>GLACER hit a snag</div>
          <div style={{ maxWidth: 420, opacity: 0.75, lineHeight: 1.5 }}>
            Something went wrong while loading the game. Your navitars and progress are saved on
            this device — reloading usually fixes it.
          </div>
          <button
            onClick={() => window.location.reload()}
            style={{
              padding: '10px 22px',
              borderRadius: 999,
              border: 'none',
              background: '#12a5c7',
              color: '#fff',
              fontWeight: 700,
              fontSize: 15,
              cursor: 'pointer',
            }}
          >
            Reload GLACER
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}

export default ShellErrorBoundary;
