import React, { lazy, Suspense, useEffect, useRef, useState } from 'react';
import { Link as RouterLink } from 'react-router-dom';
import { Box, Button, ButtonGroup, CircularProgress, Paper, Typography } from '@mui/material';
import { useNavitarFightClub } from '../contexts/NavitarFightClub';
import { SwapNavitarButton } from '../components/QuickSwapNavitar';
import { resolveNavitarArt } from '../utils/navitarArt';
import { resolveShowcaseModel } from '../utils/modelResolution';
import { AVATAR_OUTFITS, loadAvatarOutfit, saveAvatarOutfit } from '../utils/avatarOutfit';
import RealmMap from './RealmMap';
import type {
  GlideVector,
  GpsTarget,
  StrollEnvironment,
  StrollWalkerKind,
} from '../components/StrollScene';
import { getCare, updateCare } from '../utils/training';

// The 3D scene lives behind React.lazy so the (large) three.js code
// splits out of the main bundle and only loads when the Stroll page is
// actually shown — same pattern as ModelViewer. The scene itself uses
// plain three.js, not @react-three/fiber (fiber 9 breaks the React 18
// build outright — see ModelCanvas).
const StrollScene = lazy(() => import('../components/StrollScene'));

// A real browser always defines WebGLRenderingContext; jsdom and
// WebGL-less environments do not. Checking for the constructor (instead
// of calling canvas.getContext) avoids a jsdom "not implemented" console
// error and skips the scene entirely where it cannot run.
function webglAvailable(): boolean {
  if (typeof window === 'undefined') return false;
  const w = window as unknown as { WebGLRenderingContext?: unknown };
  return typeof w.WebGLRenderingContext !== 'undefined';
}

const Stroll: React.FC = () => {
  const { userNavitar, businessNavitars } = useNavitarFightClub();
  // One-shot gate: no WebGL, no scene attempt at all — the page stays a
  // friendly message instead of a blank canvas or a crash.
  const [canRender3d] = useState(() => webglAvailable());
  // The environment pick persists (Round 9, Item 6b — the stroll
  // setup Eddie picks goes with him): stored under the glacer-*
  // key convention, defaulting to the forest.
  const ENV_KEY = 'glacer-stroll-environment';
  const [environment, setEnvironment] = useState<StrollEnvironment>(() => {
    try {
      return localStorage.getItem(ENV_KEY) === 'city' ? 'city' : 'forest';
    } catch {
      return 'forest';
    }
  });
  useEffect(() => {
    try {
      localStorage.setItem(ENV_KEY, environment);
    } catch {
      // Best-effort: the pick still holds for the session.
    }
  }, [environment]);
  // Stroll's two views (Round 8, Eddie 2026-11-16: "Is the new map
  // available for Stroll view?"): the 3D stroll, or the World Map —
  // the REAL RealmMap component (same heat-glow privacy model, same
  // venue markers and wild drift, same check-in state), not a
  // second map. Your marker walks it live and your companion trails
  // behind it there.
  const [strollView, setStrollView] = useState<'scene' | 'map'>('scene');
  // The avatar's outfit: a swappable character look, persisted by id.
  // The scene applies it live; the picker just switches the id.
  const [outfit, setOutfit] = useState(() => loadAvatarOutfit());
  // WALK TRAINING (Round 9, Eddie 2026-11-16: "you walk and train
  // with your navitar"): the scene accumulates the walker's real
  // travelled distance into strollDistanceRef; the interval below
  // converts it, in blocks, into care XP + bond for the companion
  // through the SAME care store the Navidex Stage reads
  // (utils/training) — no parallel progression. PLACEHOLDER RATE
  // (Eddie tunes later): +5 XP and +1 bond per 25 world units of
  // real travel. Standing still accrues nothing — only distance
  // the scene measured counts, and a scene remount (companion
  // swap) rebaselines instead of minting phantom travel.
  const WALK_UNITS_PER_BLOCK = 25;
  const WALK_XP_PER_BLOCK = 5;
  const WALK_BOND_PER_BLOCK = 1;
  const strollDistanceRef = useRef(0);
  const accrualRef = useRef({ seen: 0, pending: 0 });
  const [strollGains, setStrollGains] = useState({ xp: 0, bond: 0 });
  // THUMB GLIDE (Round 8): the page owns the gesture — an overlay on
  // the scene's lower screen writes the live screen-space vector
  // here and the scene turns it into travel (see GlideVector). The
  // origin lives in a ref (move handlers must never chase stale
  // state); the knob's render offset lives in state.
  const glideRef = useRef<GlideVector | null>(null);
  const glideOrigin = useRef<{ x: number; y: number } | null>(null);
  const [glideKnob, setGlideKnob] = useState<{
    ox: number;
    oy: number;
    dx: number;
    dy: number;
  } | null>(null);
  const glideHandlers = {
    onPointerDown: (e: React.PointerEvent<HTMLDivElement>) => {
      const rect = e.currentTarget.getBoundingClientRect();
      // Capture keeps the glide alive when the thumb drifts off the
      // zone's edge — but some WebViews throw for pointers they
      // don't track, and a failed capture must never kill the glide
      // itself, so it is best-effort only.
      try {
        e.currentTarget.setPointerCapture(e.pointerId);
      } catch {
        /* glide on without capture */
      }
      const ox = e.clientX - rect.left;
      const oy = e.clientY - rect.top;
      glideOrigin.current = { x: ox, y: oy };
      glideRef.current = { x: 0, y: 0 };
      setGlideKnob({ ox, oy, dx: 0, dy: 0 });
    },
    onPointerMove: (e: React.PointerEvent<HTMLDivElement>) => {
      const origin = glideOrigin.current;
      if (!origin) return;
      const rect = e.currentTarget.getBoundingClientRect();
      let vx = (e.clientX - rect.left - origin.x) / 56;
      let vy = (e.clientY - rect.top - origin.y) / 56;
      const len = Math.hypot(vx, vy);
      if (len > 1) {
        vx /= len;
        vy /= len;
      }
      glideRef.current = { x: vx, y: vy };
      setGlideKnob({ ox: origin.x, oy: origin.y, dx: vx * 44, dy: vy * 44 });
    },
    onPointerUp: () => {
      glideOrigin.current = null;
      glideRef.current = null;
      setGlideKnob(null);
    },
    onPointerCancel: () => {
      glideOrigin.current = null;
      glideRef.current = null;
      setGlideKnob(null);
    },
  };

  // THE COMPANION (Eddie, 2026-11-14, refined 2026-11-16 ~09:29):
  // the companion is the navitar selected in the Navidex, i.e. the
  // FightClub active navitar (the collection in glacer-user-navitars
  // + the active id in glacer-active-navitar-id; the Navidex, the
  // battle Step 1 picker and Profile all write that same selection).
  // Stroll now HAS a Swap button (Eddie's swap-everywhere ask) —
  // but it is not a Stroll-only picker: QuickSwapNavitar writes
  // through that same FightClub setActiveNavitar path, so the
  // Navidex choice stays the single source of truth and the
  // companion (model + name, derived from userNavitar below)
  // updates immediately, in regular stroll and in AR alike.
  // The companion's effective 3D model resolves exactly like the
  // battle stage's showcase model: the record's own model first,
  // then a name+element match against the modeled demo opponents,
  // the venue fighters, and the NAVITAR_MODELS registry.
  // The chain itself is shared with the AR View page
  // (utils/modelResolution.ts) so the companion resolves its model
  // identically on every surface.
  const companionModel = userNavitar ? resolveShowcaseModel(userNavitar, businessNavitars) : null;

  const companion = userNavitar
    ? {
        name: userNavitar.name,
        element: userNavitar.element,
        modelUrl: companionModel?.modelUrl,
        modelZoom: companionModel?.modelZoom ?? userNavitar.modelZoom,
        imageUrl: resolveNavitarArt(userNavitar.imageUrl, userNavitar.name),
      }
    : null;
  const companionHasModel = !!companionModel?.modelUrl;

  // COMPANION RULE (Eddie, 2026-11-14): the walker IS the Navidex
  // companion whenever there is one — the wave-4 "Walk as" humanoid
  // toggle is RETIRED (it was a second selection surface, and Eddie
  // banned those in Stroll). The dress-up avatar walks only when the
  // player has no navitar yet. The old glacer-stroll-walk-as
  // preference is simply no longer read.
  const walkerKind: StrollWalkerKind = userNavitar ? 'navitar' : 'avatar';

  // Walk-training conversion (see WALK_* above): every 500ms,
  // read the scene's travelled total, bank the fresh distance,
  // and convert whole 25-unit blocks into care for the CURRENT
  // companion. Runs only in the scene view (the map view has no
  // StrollScene mounted; its ref simply stops moving).
  const companionName = companion?.name ?? null;
  useEffect(() => {
    if (strollView !== 'scene') return;
    const id = window.setInterval(() => {
      const acc = accrualRef.current;
      const total = strollDistanceRef.current;
      if (total < acc.seen) acc.seen = total; // scene remounted — rebaseline
      const fresh = total - acc.seen;
      acc.seen = total;
      if (fresh > 0) acc.pending += fresh;
      if (!companionName) {
        // Solo stroll: nobody to train — distance is discarded,
        // never banked for a companion picked up later.
        acc.pending = 0;
        return;
      }
      const blocks = Math.floor(acc.pending / WALK_UNITS_PER_BLOCK);
      if (blocks <= 0) return;
      acc.pending -= blocks * WALK_UNITS_PER_BLOCK;
      const care = getCare(companionName);
      updateCare(companionName, {
        xp: care.xp + blocks * WALK_XP_PER_BLOCK,
        bond: care.bond + blocks * WALK_BOND_PER_BLOCK,
      });
      setStrollGains(g => ({
        xp: g.xp + blocks * WALK_XP_PER_BLOCK,
        bond: g.bond + blocks * WALK_BOND_PER_BLOCK,
      }));
    }, 500);
    return () => window.clearInterval(id);
  }, [strollView, companionName]);

  // ---------- AR camera mode (Step 6, Eddie 2026-11-14) ----------
  // The page owns the camera stream; the scene renders transparent
  // over it with the companion's REAL 3D model in the frame. States
  // are honest: no model -> an in-stage panel says so and routes to
  // the Navidex; camera denied/unavailable -> a note + the normal
  // stroll keeps running (never a black screen, never a fake feed).
  const [arOn, setArOn] = useState(false);
  const [camState, setCamState] = useState<'off' | 'starting' | 'on' | 'denied' | 'unavailable'>(
    'off'
  );
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const parallax = useRef({ x: 0, y: 0 });
  // The companion HAS a model on paper but the GLB failed to load
  // (phone check, 2026-11-14): in AR that must surface the same
  // honest no-model panel — a card never appears in AR.
  const [arModelFailed, setArModelFailed] = useState(false);
  useEffect(() => {
    setArModelFailed(false);
  }, [companion?.name]);
  const arNoModel = arOn && !!companion && (!companionHasModel || arModelFailed);
  const arLive = arOn && camState === 'on' && !arNoModel;

  const stopStream = () => {
    streamRef.current?.getTracks().forEach(t => t.stop());
    streamRef.current = null;
    if (videoRef.current) videoRef.current.srcObject = null;
  };

  useEffect(() => {
    if (!arOn || !companion || !companionHasModel) {
      stopStream();
      setCamState('off');
      return;
    }
    if (!navigator.mediaDevices?.getUserMedia) {
      setCamState('unavailable');
      return;
    }
    let cancelled = false;
    setCamState('starting');
    navigator.mediaDevices
      .getUserMedia({ video: { facingMode: 'environment' }, audio: false })
      .then(stream => {
        if (cancelled) {
          stream.getTracks().forEach(t => t.stop());
          return;
        }
        streamRef.current = stream;
        if (videoRef.current) videoRef.current.srcObject = stream;
        setCamState('on');
      })
      .catch(() => {
        if (!cancelled) setCamState('denied');
      });
    return () => {
      cancelled = true;
    };
  }, [arOn, companion?.name, companionHasModel]);

  useEffect(() => {
    if (camState === 'on' && videoRef.current && streamRef.current) {
      videoRef.current.srcObject = streamRef.current;
    }
  }, [camState]);

  useEffect(() => stopStream, []);

  // Gentle device-orientation parallax while AR is live. No
  // permission is requested: where the browser fires the event the
  // tilt leans the view a little; where it doesn't, nothing moves.
  useEffect(() => {
    if (!arLive) return;
    const onTilt = (e: DeviceOrientationEvent) => {
      const gx = (e.gamma ?? 0) / 30;
      const gy = ((e.beta ?? 40) - 40) / 30;
      parallax.current = {
        x: Math.max(-1, Math.min(1, gx)),
        y: Math.max(-1, Math.min(1, gy)),
      };
    };
    window.addEventListener('deviceorientation', onTilt);
    return () => window.removeEventListener('deviceorientation', onTilt);
  }, [arLive]);

  // "Walk with me" — Pokémon-Go mode. The watch lives here on the
  // page; the scene only reads the latest target. Scale: 1 real
  // metre = 3 scene units, so a real walking pace (~1.4 m/s) moves
  // the navitar at ~4.2 units/s — the same pleasant pace as the
  // manual WALK_SPEED. Fixes closer than 1.5 m to the last accepted
  // one are ignored as GPS jitter. INTEGRITY: this is cosmetic
  // only — it never touches the checked-in venue, presence, or any
  // networking state.
  const GPS_SCALE = 3;
  const [gpsOn, setGpsOn] = useState(false);
  const [gpsNote, setGpsNote] = useState<string | null>(null);
  const gpsTarget = useRef<GpsTarget | null>(null);
  const gpsOrigin = useRef<{ lat: number; lon: number } | null>(null);
  const gpsLast = useRef<{ lat: number; lon: number } | null>(null);
  useEffect(() => {
    if (!gpsOn) {
      gpsTarget.current = null;
      gpsOrigin.current = null;
      gpsLast.current = null;
      setGpsNote(null);
      return;
    }
    if (!('geolocation' in navigator)) {
      setGpsNote('Location is off — guide him with the glide or WASD keys');
      return;
    }
    const watchId = navigator.geolocation.watchPosition(
      pos => {
        const { latitude, longitude } = pos.coords;
        if (!gpsOrigin.current) {
          gpsOrigin.current = { lat: latitude, lon: longitude };
          gpsLast.current = { lat: latitude, lon: longitude };
          return;
        }
        const last = gpsLast.current ?? gpsOrigin.current;
        const dLat = (latitude - last.lat) * 110540;
        const dLon = (longitude - last.lon) * 111320 * Math.cos((last.lat * Math.PI) / 180);
        if (Math.hypot(dLat, dLon) < 1.5) return; // jitter — ignore
        gpsLast.current = { lat: latitude, lon: longitude };
        const origin = gpsOrigin.current;
        const east = (longitude - origin.lon) * 111320 * Math.cos((origin.lat * Math.PI) / 180);
        const north = (latitude - origin.lat) * 110540;
        const x = Math.max(-82, Math.min(82, east * GPS_SCALE));
        const z = Math.max(-82, Math.min(82, -north * GPS_SCALE));
        gpsTarget.current = { x, z, heading: Math.atan2(x, z) };
        setGpsNote(null);
      },
      () => {
        setGpsNote('Location is off — guide him with the glide or WASD keys');
      },
      { enableHighAccuracy: true, maximumAge: 1000 }
    );
    return () => navigator.geolocation.clearWatch(watchId);
  }, [gpsOn]);

  return (
    <Box sx={{ p: 2, maxWidth: 1000, margin: '0 auto' }}>
      <Paper sx={{ p: 2, mb: 2 }}>
        <Typography variant="h4" gutterBottom>
          Stroll
        </Typography>
        <Typography variant="body1" color="text.secondary" paragraph>
          Take a walk with your navitar — through the woods, or down the city streets.
        </Typography>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 2, alignItems: 'center', mb: 2 }}>
          <ButtonGroup aria-label="Stroll view">
            <Button
              variant={strollView === 'scene' ? 'contained' : 'outlined'}
              aria-pressed={strollView === 'scene'}
              onClick={() => setStrollView('scene')}
            >
              🧍 Stroll
            </Button>
            <Button
              variant={strollView === 'map' ? 'contained' : 'outlined'}
              aria-pressed={strollView === 'map'}
              onClick={() => setStrollView('map')}
            >
              🗺️ World Map
            </Button>
          </ButtonGroup>
          <Typography variant="body1">
            {companion ? `Strolling with ${companion.name}` : 'Strolling solo — no navitar yet'}
          </Typography>
          {companion && <SwapNavitarButton label="🔄 Swap companion" variant="contained" />}
          {strollView === 'scene' && (
            <Button component={RouterLink} to="/map" variant="outlined" sx={{ ml: 'auto' }}>
              Back to map
            </Button>
          )}
        </Box>
        {strollView === 'map' && (
          <Typography variant="body2" color="text.secondary">
            The World Map, right here in Stroll — the same map as the Map tab: heat glow for areas,
            pins only for friends, your marker walking it live as you move, and{' '}
            {companion
              ? `${companion.name} trailing a step or two behind you`
              : 'your companion beside you once you have one'}
            . Check-in is the same state everywhere.
          </Typography>
        )}
        {strollView === 'scene' && (
          <>
            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 2, alignItems: 'center' }}>
              <ButtonGroup aria-label="Stroll environment">
                <Button
                  variant={environment === 'forest' ? 'contained' : 'outlined'}
                  aria-pressed={environment === 'forest'}
                  disabled={arLive}
                  onClick={() => setEnvironment('forest')}
                >
                  🌲 Forest
                </Button>
                <Button
                  variant={environment === 'city' ? 'contained' : 'outlined'}
                  aria-pressed={environment === 'city'}
                  disabled={arLive}
                  onClick={() => setEnvironment('city')}
                >
                  🌆 City
                </Button>
              </ButtonGroup>
            </Box>
            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 2, alignItems: 'center', mt: 2 }}>
              <Button
                variant={arOn ? 'contained' : 'outlined'}
                aria-pressed={arOn}
                aria-label="AR camera"
                disabled={!companion}
                onClick={() => setArOn(on => !on)}
              >
                📷 AR camera
              </Button>
              <Button
                variant={gpsOn ? 'contained' : 'outlined'}
                aria-pressed={gpsOn}
                aria-label="Walk with me (GPS)"
                disabled={arLive}
                onClick={() => setGpsOn(on => !on)}
              >
                📍 Walk with me
              </Button>
              {!companion && (
                <Typography variant="body2" color="text.secondary">
                  AR needs a navitar companion first — your Navidex companion is the one who appears
                  in AR.
                </Typography>
              )}
            </Box>
            <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
              {companion
                ? `You are walking as ${companion.name} — your Navidex companion stays with you in Stroll: the world runs three times farther than it used to, and the fog softens the edge.`
                : 'Your avatar walks alone until you have a navitar.'}
            </Typography>
            {arOn && (camState === 'denied' || camState === 'unavailable') && (
              <Typography variant="body2" sx={{ mt: 1, color: 'warning.main' }} role="note">
                📷 Camera unavailable — AR needs camera access, so you&apos;re still strolling
                normally. Check the browser&apos;s camera permission, then toggle AR camera again.
              </Typography>
            )}
            {gpsNote && (
              <Typography variant="body2" sx={{ mt: 1, color: 'warning.main' }} role="note">
                {gpsNote}
              </Typography>
            )}
            {companion && (
              <Typography variant="body2" sx={{ mt: 1, color: '#9be15d' }} role="status">
                🚶 Training walk · +{strollGains.xp} XP · +{strollGains.bond} bond for{' '}
                {companion.name} this stroll
                {strollGains.xp === 0 ? ' — training lands as you cover real ground together' : ''}
              </Typography>
            )}
            <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
              WASD or arrow keys to walk — W forward, A / D to turn, S to step back. On touch, glide
              a thumb across the lower screen: your avatar travels the way you glide, and stops when
              you lift. Drag the upper scene to look around; the camera follows behind you. Trees
              and buildings are scenery for now — you can walk straight through them. Walking
              together trains your companion: real distance on foot earns XP and bond, back in the
              Navidex. With Walk with me on, your navitar follows your real footsteps (the glide and
              WASD still override); it is a cosmetic stroll only — it never changes your check-in or
              who can see you. AR camera puts your companion&apos;s real 3D model in your camera
              view instead: the glide moves him within the frame (glide up = farther away, down =
              nearer), Walk with me pauses while AR is on, and AR never touches check-in or presence
              either.
            </Typography>
            {/* Outfit picker: the avatar is a character you dress up, not a
            likeness of anyone. New outfits only need an entry in
            src/utils/avatarOutfit.ts to appear here — shop and earned
            looks plug into this same picker later. */}
            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, alignItems: 'center', mt: 2 }}>
              <Typography variant="body2" color="text.secondary">
                Outfit:
              </Typography>
              {AVATAR_OUTFITS.map(o => (
                <Button
                  key={o.id}
                  size="small"
                  variant={outfit.id === o.id ? 'contained' : 'outlined'}
                  aria-label={`Wear ${o.name} outfit`}
                  aria-pressed={outfit.id === o.id}
                  onClick={() => {
                    saveAvatarOutfit(o.id);
                    setOutfit(o);
                  }}
                >
                  {o.name} · {o.tag}
                </Button>
              ))}
            </Box>
            <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
              Your avatar is a character you can dress up — outfits are swappable, and more looks
              (shop or earned) can plug in here later.
            </Typography>
          </>
        )}
      </Paper>

      {strollView === 'map' ? (
        <RealmMap />
      ) : (
        <>
          {!userNavitar && (
            <Paper sx={{ p: 2, mb: 2, border: '1px solid', borderColor: 'primary.main' }}>
              <Typography variant="h6" gutterBottom>
                Create a navitar first
              </Typography>
              <Typography variant="body2" color="text.secondary" paragraph>
                You can stroll on your own right now, but your navitar will walk beside you once you
                have one.
              </Typography>
              <Button component={RouterLink} to="/battle" variant="contained">
                Create a navitar
              </Button>
            </Paper>
          )}

          {arNoModel && companion ? (
            // Honest no-model state (companion rule): AR never fakes a
            // stand-in, and selection never happens in Stroll — the
            // route leads to the Navidex, the one place a companion is
            // chosen. Rendered in place of the stage (and ahead of the
            // WebGL gate: the no-model fact is the more specific state).
            <Paper
              sx={{
                p: 3,
                minHeight: 300,
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                gap: 1.5,
                textAlign: 'center',
              }}
            >
              <Typography variant="h6">
                {companion.name} doesn&apos;t have a 3D model yet
              </Typography>
              <Typography variant="body2" color="text.secondary" sx={{ maxWidth: 420 }}>
                AR stroll shows your companion&apos;s real 3D model in the camera — never a picture
                or a stand-in. Swap to a companion with a 3D model — here, or in the Navidex — and
                that companion stays with you here.
              </Typography>
              <SwapNavitarButton label="🔄 Swap companion" variant="contained" />
              <Button component={RouterLink} to="/collection" variant="outlined">
                Choose your companion in the Navidex
              </Button>
              <Button onClick={() => setArOn(false)}>Back to stroll</Button>
            </Paper>
          ) : canRender3d ? (
            <Box
              sx={{
                width: '100%',
                height: 560,
                position: 'relative',
                borderRadius: '16px',
                overflow: 'hidden',
                bgcolor: '#121212',
              }}
            >
              {/* The live camera feed sits UNDER the transparent scene
              canvas while AR is on. It renders only in AR; the stream
              attaches via the camState effect above. */}
              {arOn && companionHasModel && camState !== 'off' && (
                <video
                  ref={videoRef}
                  autoPlay
                  playsInline
                  muted
                  style={{
                    position: 'absolute',
                    inset: 0,
                    width: '100%',
                    height: '100%',
                    objectFit: 'cover',
                    zIndex: 0,
                  }}
                />
              )}
              <Box sx={{ position: 'absolute', inset: 0, zIndex: 1 }}>
                <Suspense
                  fallback={
                    <Box
                      sx={{
                        width: '100%',
                        height: '100%',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        gap: 1,
                      }}
                    >
                      <CircularProgress size={20} />
                      <Typography variant="body2">Loading the stroll…</Typography>
                    </Box>
                  }
                >
                  <StrollScene
                    environment={environment}
                    companion={companion}
                    outfit={outfit}
                    walkerKind={walkerKind}
                    gpsTarget={gpsTarget}
                    glideRef={glideRef}
                    distanceRef={strollDistanceRef}
                    arMode={arLive}
                    parallax={parallax}
                    onModelLoadError={() => setArModelFailed(true)}
                  />
                </Suspense>
              </Box>
              {/* Swap in the controls layer too (Eddie, 2026-11-16):
              reachable in AR mode, same sheet, same write path. */}
              {companion && !arNoModel && (
                <Box sx={{ position: 'absolute', left: 16, top: 16, zIndex: 3 }}>
                  <SwapNavitarButton label="🔄 Swap companion" variant="contained" size="small" />
                </Box>
              )}
              {/* THUMB GLIDE (Round 8): the lower ~46% of the scene is a
              glide surface — glide a thumb anywhere on it and the
              avatar travels that way at walking pace, turning toward
              the glide; lift to stop. Since Round 9 it owns the lower
              screen outright: the on-screen walk buttons that used to
              sit above it were removed on Eddie's order (the glide
              superseded them), so nothing competes with the thumb
              down here. The canvas keeps the upper scene for
              drag-to-look — the named split: look up top, walk down
              low. */}
              {!arNoModel && (
                <Box
                  data-testid="stroll-glide-zone"
                  aria-label="Glide here to walk"
                  sx={{
                    position: 'absolute',
                    left: 0,
                    right: 0,
                    bottom: 0,
                    height: '46%',
                    zIndex: 1,
                    touchAction: 'none',
                    cursor: 'grab',
                  }}
                  {...glideHandlers}
                >
                  {!glideKnob && (
                    <Box
                      sx={{
                        position: 'absolute',
                        left: 16,
                        bottom: 16,
                        pointerEvents: 'none',
                        px: 1.25,
                        py: 0.5,
                        borderRadius: 999,
                        bgcolor: 'rgba(6, 24, 33, 0.55)',
                        color: '#e8f6fb',
                        fontSize: '0.8rem',
                      }}
                    >
                      👆 Glide here to walk
                    </Box>
                  )}
                  {glideKnob && (
                    <>
                      <Box
                        sx={{
                          position: 'absolute',
                          left: glideKnob.ox - 56,
                          top: glideKnob.oy - 56,
                          width: 112,
                          height: 112,
                          borderRadius: '50%',
                          border: '2px solid rgba(232, 246, 251, 0.5)',
                          bgcolor: 'rgba(6, 24, 33, 0.25)',
                          pointerEvents: 'none',
                        }}
                      />
                      <Box
                        sx={{
                          position: 'absolute',
                          left: glideKnob.ox + glideKnob.dx - 22,
                          top: glideKnob.oy + glideKnob.dy - 22,
                          width: 44,
                          height: 44,
                          borderRadius: '50%',
                          bgcolor: 'rgba(232, 246, 251, 0.75)',
                          pointerEvents: 'none',
                        }}
                      />
                    </>
                  )}
                </Box>
              )}
            </Box>
          ) : (
            <Paper sx={{ p: 3 }}>
              <Typography variant="h6" gutterBottom>
                The 3D stroll needs WebGL
              </Typography>
              <Typography variant="body2" color="text.secondary">
                This browser can&apos;t run WebGL, so the stroll can&apos;t load here. Your navitar
                is safe — you can still see it on the map and in your Navidex.
              </Typography>
            </Paper>
          )}
        </>
      )}
    </Box>
  );
};

export default Stroll;
