// Venue buzz — promotions, events and invites for DEMO venues
// (Eddie, 2026-11-16). A venue with something on gets two things:
// a side pop-up delivered by the player's navitar (see
// components/VenueNotification.tsx) and a GLOWING marker on the
// World Map whose look the VENUE chose (its glow theme).
//
// DEMO SCOPE, honestly framed: every entry below hangs on a demo
// venue from data/venues.ts (fictional bars / public places). No
// offers are invented for real named businesses. When a real venue
// joins, its own promo/event/invite copy and its chosen glow theme
// replace these demo entries — the For Venues signup (/venues)
// already asks a venue to pick its theme.

export type GlowThemeId = 'fire' | 'ice' | 'electric' | 'gold' | 'shadow' | 'nature';

export interface GlowTheme {
  id: GlowThemeId;
  name: string;
  emoji: string;
  // CSS modifier class on the venue marker (styles/modern.css).
  className: string;
}

export const GLOW_THEMES: Record<GlowThemeId, GlowTheme> = {
  fire: { id: 'fire', name: 'On Fire', emoji: '🔥', className: 'glow-fire' },
  ice: { id: 'ice', name: 'Ice Glow', emoji: '❄️', className: 'glow-ice' },
  electric: { id: 'electric', name: 'Electric', emoji: '⚡', className: 'glow-electric' },
  gold: { id: 'gold', name: 'Golden Spotlight', emoji: '✨', className: 'glow-gold' },
  shadow: { id: 'shadow', name: 'Shadow Pulse', emoji: '🌑', className: 'glow-shadow' },
  nature: { id: 'nature', name: 'Nature Bloom', emoji: '🌿', className: 'glow-nature' },
};

export const GLOW_THEME_LIST: GlowTheme[] = Object.values(GLOW_THEMES);

// Battle-night stage colors per theme (add-on, Eddie 2026-11-16):
// the venue's glow theme also runs its battle nights — these two
// colors tint the battle STAGE/frame (wash, rim glow, banner, VS
// line). Fighter attack FX keep their own element colors; the
// theme never recolors an attack.
export const THEME_STAGE_COLORS: Record<GlowThemeId, { primary: string; secondary: string }> = {
  fire: { primary: '#ff7a18', secondary: '#ff3d00' },
  ice: { primary: '#54c8ff', secondary: '#b3e5fc' },
  electric: { primary: '#be78ff', secondary: '#ffeb3b' },
  gold: { primary: '#ffc83c', secondary: '#ff9800' },
  shadow: { primary: '#8a4fff', secondary: '#311b92' },
  nature: { primary: '#5ad678', secondary: '#2e7d32' },
};

export interface VenueBuzz {
  venueId: string;
  // The theme THIS venue picked for its map glow.
  glowTheme: GlowThemeId;
  promo?: string;
  event?: { name: string; when: string };
  invite?: string;
}

export const DEMO_VENUE_BUZZ: VenueBuzz[] = [
  {
    venueId: 'venue-ember',
    glowTheme: 'fire',
    event: { name: 'Battle Night', when: 'Tonight from 7pm' },
    promo: 'Battle Night perk: win a duel here tonight and the winner’s perk unlocks at the bar.',
  },
  {
    venueId: 'venue-marquee',
    glowTheme: 'electric',
    promo:
      'Live-music nights: checked-in GLACER players get the free-cover perk — check in to claim it.',
  },
  {
    venueId: 'venue-santa-monica-beach',
    glowTheme: 'gold',
    event: { name: 'Sunset Battle Social', when: 'Today at golden hour' },
  },
  {
    venueId: 'venue-griffith-park',
    glowTheme: 'nature',
    invite:
      'Griffith Park invites you: a sunrise Stroll meetup this weekend — bring your navitar and walk with the crew.',
  },
];

export function buzzForVenue(venueId: string): VenueBuzz | undefined {
  return DEMO_VENUE_BUZZ.find(b => b.venueId === venueId);
}

// A venue glows when something is actually ON there — a live event
// or an active promo. (An invite alone is personal, not a broadcast,
// so it never lights the marker.)
export function venueHasLiveBuzz(buzz: VenueBuzz | undefined): boolean {
  return !!buzz && (!!buzz.event || !!buzz.promo);
}

export type VenueNoticeKind = 'promo' | 'event' | 'invite';

export interface VenueNotice {
  id: string;
  venueId: string;
  kind: VenueNoticeKind;
  headline: string;
  body: string;
}

// Flatten the buzz into individual notices, events first (they're
// time-boxed), then promos, then invites.
export function allVenueNotices(): VenueNotice[] {
  const notices: VenueNotice[] = [];
  for (const buzz of DEMO_VENUE_BUZZ) {
    if (buzz.event) {
      notices.push({
        id: `${buzz.venueId}-event`,
        venueId: buzz.venueId,
        kind: 'event',
        headline: buzz.event.name,
        body: `${buzz.event.when}.`,
      });
    }
  }
  for (const buzz of DEMO_VENUE_BUZZ) {
    if (buzz.promo) {
      notices.push({
        id: `${buzz.venueId}-promo`,
        venueId: buzz.venueId,
        kind: 'promo',
        headline: 'Promotion',
        body: buzz.promo,
      });
    }
  }
  for (const buzz of DEMO_VENUE_BUZZ) {
    if (buzz.invite) {
      notices.push({
        id: `${buzz.venueId}-invite`,
        venueId: buzz.venueId,
        kind: 'invite',
        headline: 'You’re invited',
        body: buzz.invite,
      });
    }
  }
  return notices;
}

// --- Map focus handoff ------------------------------------------------
// Tapping a venue notice takes the player to that venue on the
// World Map: the notice stashes the venue id here, and RealmMap
// consumes it on mount (select + fly to). sessionStorage, one-shot.
const VENUE_FOCUS_KEY = 'glacer-venue-focus';

export function setVenueFocus(venueId: string): void {
  try {
    sessionStorage.setItem(VENUE_FOCUS_KEY, venueId);
  } catch {
    // Private mode: the map simply opens unfocused.
  }
}

export function consumeVenueFocus(): string | null {
  try {
    const id = sessionStorage.getItem(VENUE_FOCUS_KEY);
    if (id) sessionStorage.removeItem(VENUE_FOCUS_KEY);
    return id;
  } catch {
    return null;
  }
}
