function isReply(v: unknown): v is ForumReply {
  const r = v as ForumReply;
  return (
    !!r &&
    typeof r === 'object' &&
    typeof r.id === 'string' &&
    typeof r.author === 'string' &&
    typeof r.body === 'string' &&
    typeof r.createdAt === 'number'
  );
}

function isThread(v: unknown): v is ForumThread {
  const t = v as ForumThread;
  return (
    !!t &&
    typeof t === 'object' &&
    typeof t.id === 'string' &&
    (t.board === 'meetups' || t.board === 'events') &&
    typeof t.title === 'string' &&
    typeof t.body === 'string' &&
    typeof t.author === 'string' &&
    typeof t.createdAt === 'number' &&
    Array.isArray(t.replies) &&
    t.replies.every(isReply)
  );
}

// First run: the seed community is written to storage so the
// player's own posts merge into one durable list. A corrupt or
// shape-mismatched store falls back to the seeds rather than
// rendering a broken board.
export function loadForums(): ForumThread[] {
  try {
    const raw = localStorage.getItem(FORUMS_KEY);
    if (raw === null) {
      const seeds = seedThreads();
      saveForums(seeds);
      return seeds;
    }
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed) || !parsed.every(isThread)) return seedThreads();
    return parsed;
  } catch {
    return seedThreads();
  }
}

export function saveForums(threads: ForumThread[]): void {
  try {
    localStorage.setItem(FORUMS_KEY, JSON.stringify(threads));
  } catch {
    // Private mode / quota: the boards still work for this session.
  }
}

let idCounter = 0;
export function newForumId(prefix: string): string {
  idCounter += 1;
  return `${prefix}-${Date.now()}-${idCounter}`;
}
