// Venue notification — a compact TOP pill delivered by the
// player's navitar (the IcebreakerNotification pattern): a demo
// venue has a promotion on, an event tonight, or an invite for
// the player. (Was a bottom-right side card until 2026-11-16 —
// Eddie: notifications stay small, at the top, and never interrupt
// a battle or the view.)
//
// Rules (Eddie, 2026-11-16):
// - One card at a time — and never stacked over an icebreaker card
//   (the icebreaker wins; this waits).
// - Dismissal is remembered for the day, per notice (mirrors the
//   icebreaker per-day dismissal pattern in PresenceContext).
// - INVITES are personal: Quiet (Just here) / Battle-only /
//   Invisible presence suppresses them. Promos and events are venue
//   broadcasts and don't need presence — but total volume stays
//   low: the first notice surfaces shortly after the app opens,
//   and each next one only after a check-in or a move to a new
//   page, never on a timer blast.
// - Tapping through takes the player to that venue on the World
//   Map (venue-focus handoff in data/venueBuzz.ts).
// Demo venues only, demo-framed on the card.
import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Box, Button, IconButton, Paper, Typography } from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import { useLocation, useNavigate } from 'react-router-dom';
import { DEMO_VENUES } from '../data/venues';
import { allVenueNotices, setVenueFocus, type VenueNotice } from '../data/venueBuzz';
import { useNavitarFightClub } from '../contexts/NavitarFightClub';
import { usePresence } from '../contexts/PresenceContext';
import { useVenue } from '../contexts/VenueContext';
import { localDateString } from '../utils/presence';
import { elementEmoji, resolveNavitarArt } from '../utils/navitarArt';
import { NavitarArtImg } from './NavitarArtImg';

const DISMISSALS_KEY = 'glacer-venue-notice-dismissals';

interface NoticeDismissal {
  id: string;
  date: string;
}

function loadDismissals(): NoticeDismissal[] {
  try {
    const raw = localStorage.getItem(DISMISSALS_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    const today = localDateString();
    return Array.isArray(parsed)
      ? parsed.filter(
          (v): v is NoticeDismissal =>
            !!v &&
            typeof v === 'object' &&
            typeof (v as NoticeDismissal).id === 'string' &&
            (v as NoticeDismissal).date === today
        )
      : [];
  } catch {
    return [];
  }
}

function saveDismissal(id: string): void {
  try {
    const next = [...loadDismissals().filter(d => d.id !== id), { id, date: localDateString() }];
    localStorage.setItem(DISMISSALS_KEY, JSON.stringify(next));
  } catch {
    // Private mode: the dismissal holds for this session via state.
  }
}

const KIND_EMOJI: Record<VenueNotice['kind'], string> = {
  event: '🎉',
  promo: '📣',
  invite: '💌',
};

const VenueNotification: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { userNavitar } = useNavitarFightClub();
  const { networkingStatus, visibility, icebreakerOffer } = usePresence();
  const { checkedInVenueId } = useVenue();
  const [dismissed, setDismissed] = useState<NoticeDismissal[]>(() => loadDismissals());
  const [shownCount, setShownCount] = useState(0);
  const [armed, setArmed] = useState(false);
  const triggerRef = useRef<string>('');

  // Invites are personal — they respect presence. Promos/events are
  // venue broadcasts.
  const invitesAllowed = networkingStatus === 'open' && visibility !== 'invisible';

  const eligible = useMemo(
    () =>
      allVenueNotices().filter(
        n => !dismissed.some(d => d.id === n.id) && (n.kind !== 'invite' || invitesAllowed)
      ),
    [dismissed, invitesAllowed]
  );

  // Trigger discipline: the first notice arms ~2.5s after the app
  // opens; after that, a notice only becomes showable when the
  // trigger changes — a check-in or a page move. shownCount is how
  // many have been presented under the current trigger.
  const trigger = `${location.pathname}|${checkedInVenueId ?? 'none'}`;
  useEffect(() => {
    if (triggerRef.current !== trigger) {
      triggerRef.current = trigger;
      setShownCount(0);
      setArmed(false);
      const t = window.setTimeout(() => setArmed(true), 1200);
      return () => window.clearTimeout(t);
    }
    return undefined;
  }, [trigger]);
  useEffect(() => {
    const t = window.setTimeout(() => setArmed(true), 2500);
    return () => window.clearTimeout(t);
  }, []);

  const current: VenueNotice | null =
    armed && !icebreakerOffer && shownCount < 1 ? (eligible[0] ?? null) : null;
  const venue = current ? DEMO_VENUES.find(v => v.id === current.venueId) : undefined;

  // Compact top pill (Eddie, 2026-11-16): the notice auto-hides
  // after a few seconds so it never sits over the game. Auto-hide
  // is NOT the remembered dismissal — it only tucks this showing
  // away (keyed by trigger + notice, so a later check-in or page
  // move can surface it again); tapping ✕ is the per-day dismissal
  // it always was.
  const [autoHiddenKey, setAutoHiddenKey] = useState<string | null>(null);
  const currentKey = current ? `${trigger}|${current.id}` : null;
  useEffect(() => {
    if (!current || !currentKey || autoHiddenKey === currentKey) return undefined;
    const t = window.setTimeout(() => setAutoHiddenKey(currentKey), 7000);
    return () => window.clearTimeout(t);
  }, [current, currentKey, autoHiddenKey]);

  if (!current || !venue || autoHiddenKey === currentKey) return null;

  const dismiss = () => {
    saveDismissal(current.id);
    setDismissed(loadDismissals());
    setShownCount(c => c + 1);
  };

  const viewOnMap = () => {
    setVenueFocus(venue.id);
    dismiss();
    navigate('/map');
  };

  const art = userNavitar ? resolveNavitarArt(userNavitar.imageUrl, userNavitar.name) : null;
  const headline =
    current.kind === 'invite'
      ? `${venue.name} invites you`
      : current.kind === 'event'
        ? `${current.headline} at ${venue.name}`
        : `${venue.name} — ${current.headline}`;

  // Compact TOP pill (Eddie, 2026-11-16): slim, top-centre under
  // the top bar — a 34px avatar, two single lines (headline, then
  // the notice body), one action, one close. It overlays only the
  // top strip of the screen, so a battle or the map underneath is
  // never interrupted. Same triggers, same suppression, same
  // per-day dismissal — only the presentation shrank and moved.
  return (
    <Paper
      data-testid="venue-notification"
      elevation={8}
      className="glacer-top-pop"
      sx={{
        position: 'fixed',
        top: { xs: 60, sm: 72 },
        left: '50%',
        zIndex: 1290,
        maxWidth: 520,
        width: 'calc(100vw - 24px)',
        px: 1.5,
        py: 1,
        borderRadius: '16px',
        display: 'flex',
        alignItems: 'center',
        gap: 1.25,
      }}
    >
      {userNavitar &&
        (art ? (
          <NavitarArtImg
            src={art}
            alt={`${userNavitar.name} art`}
            element={userNavitar.element}
            style={{
              width: 34,
              height: 34,
              borderRadius: '50%',
              flexShrink: 0,
              objectFit: 'cover',
            }}
          />
        ) : (
          <Box
            sx={{
              width: 34,
              height: 34,
              borderRadius: '50%',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '1.05rem',
              flexShrink: 0,
              bgcolor: 'rgba(18, 165, 199, 0.15)',
            }}
          >
            {elementEmoji(userNavitar.element)}
          </Box>
        ))}
      <Box sx={{ flex: 1, minWidth: 0 }}>
        <Typography
          sx={{
            fontSize: '0.85rem',
            fontWeight: 700,
            lineHeight: 1.25,
            whiteSpace: 'nowrap',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
          }}
        >
          {KIND_EMOJI[current.kind]} {headline}
        </Typography>
        <Typography
          variant="caption"
          color="text.secondary"
          sx={{
            display: 'block',
            whiteSpace: 'nowrap',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
          }}
        >
          DEMO · {current.body}
        </Typography>
      </Box>
      <Button variant="contained" size="small" onClick={viewOnMap} sx={{ flexShrink: 0 }}>
        View map
      </Button>
      <IconButton
        size="small"
        onClick={dismiss}
        aria-label="Dismiss venue notice"
        sx={{ flexShrink: 0 }}
      >
        <CloseIcon fontSize="small" />
      </IconButton>
    </Paper>
  );
};

export default VenueNotification;
